// One prompt for all Logwatch emails found, plus their IDs for deletion later.
// Logwatch sends plain text; HTML is a fallback in case a mail client rewrote it.
const MAX_CHARS_PER_REPORT = 20000;

const reports = $input.all().map(({ json: mail }) => {
  let body = mail.text || '';
  if (!body && mail.html) {
    body = mail.html
      .replace(/<style[\s\S]*?<\/style>/gi, '')
      .replace(/<br\s*\/?>/gi, '\n')
      .replace(/<[^>]+>/g, ' ')
      .replace(/&nbsp;/g, ' ')
      .replace(/&lt;/g, '<')
      .replace(/&gt;/g, '>')
      .replace(/&amp;/g, '&');
  }
  body = body.replace(/[ \t]+\n/g, '\n').replace(/\n{3,}/g, '\n\n').trim();
  if (body.length > MAX_CHARS_PER_REPORT) {
    body = body.slice(0, MAX_CHARS_PER_REPORT) + '\n[report truncated]';
  }
  return {
    id: mail.id,
    subject: mail.subject || mail.Subject || '(no subject)',
    date: mail.date || '',
    body,
  };
}).filter(r => r.id && r.body);

if (reports.length === 0) return [];

const reportText = reports
  .map((r, n) => `=== REPORT ${n + 1}: ${r.subject} (${r.date}) ===\n${r.body}`)
  .join('\n\n');

return [{
  json: {
    reportCount: reports.length,
    emailIds: reports.map(r => r.id),
    reportText,
  },
}];

// Pull the text out of the Gemini response and build the Telegram message.
const item = $input.first().json;
let text = '';
if (item?.content?.parts) {
  text = item.content.parts.map(p => p.text || '').join('');
} else if (item?.candidates) {
  text = item.candidates
    .map(c => c.content?.parts?.map(p => p.text || '').join('') || '')
    .join('');
} else if (item?.message?.content) {
  text = item.message.content;
} else if (item?.text) {
  text = item.text;
} else if (item?.output) {
  text = item.output;
}
text = String(text).replace(/\\n/g, '\n').trim();

// An empty answer must not lead to deleting the emails unread.
if (!text) {
  throw new Error('Gemini returned an empty summary; the Logwatch emails were kept.');
}

const prepared = $('Prepare Reports').first().json;
const day = new Date().toISOString().slice(0, 10);
const header = `Logwatch summary, ${day} (${prepared.reportCount} report${prepared.reportCount === 1 ? '' : 's'})`;

// Telegram rejects messages over 4096 characters.
let message = `${header}\n\n${text}`;
if (message.length > 4000) {
  message = message.slice(0, 3980) + '\n[cut to fit Telegram]';
}

return [{ json: { message, emailIds: prepared.emailIds } }];

// One item per email, so the Gmail node deletes each of them.
const ids = $('Format Message').first().json.emailIds || [];
return ids.map(id => ({ json: { messageId: id } }));
